    "拖動滑片減小電阻 → 電流增大 → 吸起的大頭針變多",
  "选中电磁铁，把匝数改为 50 / 150 匝比较":
    "選中電磁鐵，把匝數改為 50 / 150 匝比較",
  "取消“插入铁芯”，磁性大大减弱": "取消“插入鐵芯”，磁性大大減弱",
  "电流表接的是 3A 量程。": "電流表接的是 3A 量程。",
  太阳能电池驱动电动机: "太陽能電池驅動電動機",
  "台灯照射太阳能电池板，产生的电能驱动小电动机；改变光照强度观察转速、电压和电流。":
    "檯燈照射太陽能電池板，產生的電能驅動小電動機；改變光照強度觀察轉速、電壓和電流。",
  "光能 → 电能 → 机械能。太阳能电池的输出随光照变化。":
    "光能 → 電能 → 機械能。太陽能電池的輸出隨光照變化。",
  "闭合开关，电动机转动": "閉合開關，電動機轉動",
  "选中太阳能电池板，在其上滚动滚轮调节光照":
    "選中太陽能電池板，在其上滾動滾輪調節光照",
  "光照减弱：电流减小，电动机变慢甚至停转":
    "光照減弱：電流減小，電動機變慢甚至停轉",
  "断开开关，电压表读数即为开路电压": "斷開開關，電壓表讀數即為開路電壓",
  "太阳能电池接近“恒流源”：短路电流与光照强度成正比。":
    "太陽能電池接近“恆流源”：短路電流與光照強度成正比。",
