  "电学虚拟实验台：自由搭建电路，实时观察电流、电压与元件状态，支持仪表测量与数据记录。":
    "電學虛擬實驗臺：自由搭建電路，實時觀察電流、電壓與元件狀態，支持儀表測量與數據記錄。",
  串并联电路: "串並聯電路",
