  "截面是五边形时，五条边分别落在正方体的 5 个面上，其中必有两组对面，对应的边互相平行，而正五边形没有平行的边，所以截不出正五边形。":
    "截面是五邊形時，五條邊分別落在正方體的 5 個面上，其中必有兩組對面，對應的邊互相平行，而正五邊形沒有平行的邊，所以截不出正五邊形。",
  "截面是三角形时，三条边落在同一个顶点处的三个面上，可以算出三个角都是锐角，所以截面不可能是直角三角形或钝角三角形。":
    "截面是三角形時，三條邊落在同一個頂點處的三個面上，可以算出三個角都是銳角，所以截面不可能是直角三角形或鈍角三角形。",
  "正四面体只有 4 个面，截面最多是四边形，不可能是五边形。平行于一组对棱、过其余棱中点的截面是正方形。":
    "正四面體只有 4 個面，截面最多是四邊形，不可能是五邊形。平行於一組對稜、過其餘稜中點的截面是正方形。",
  "AC、CD₁、D₁A 都是正方体的面对角线，长度都是 2√2，所以截面是正三角形。":
    "AC、CD₁、D₁A 都是正方體的面對角線，長度都是 2√2，所以截面是正三角形。",
  "截面为 BB₁D₁D：BD = 2√2，BB₁ = 2，且 BB₁ ⊥ BD，所以是矩形而不是正方形。":
    "截面為 BB₁D₁D：BD = 2√2，BB₁ = 2，且 BB₁ ⊥ BD，所以是矩形而不是正方形。",
  "正方体的展开图共 11 种：“一四一”型 6 种、“二三一”型 3 种、“二二二”型 1 种、“三三”型 1 种。含“田”字、一行超过 4 个面或“凹”字形的都不能折成正方体。":
    "正方體的展開圖共 11 種：“一四一”型 6 種、“二三一”型 3 種、“二二二”型 1 種、“三三”型 1 種。含“田”字、一行超過 4 個面或“凹”字形的都不能折成正方體。",
  "展开图中，同一行或同一列里隔着一个面的两个面相对；“Z”字形两端的面也相对。":
    "展開圖中，同一行或同一列裡隔著一個面的兩個面相對；“Z”字形兩端的面也相對。",
  "先由俯视图确定每个位置有没有方块，再由主视图、左视图确定各列、各行的最高层数，逐个排除。":
    "先由俯視圖確定每個位置有沒有方塊，再由主視圖、左視圖確定各列、各行的最高層數，逐個排除。",
  "俯视图的每个位置至少放 1 个；主视图中每一列的最高层数，只要在该列的某一个位置达到即可。":
    "俯視圖的每個位置至少放 1 個；主視圖中每一列的最高層數，只要在該列的某一個位置達到即可。",
  "俯视图的每个位置都可以堆到主视图中该列的最高层数。":
    "俯視圖的每個位置都可以堆到主視圖中該列的最高層數。",
