  搭法丙: "搭法丙",
  变换: "變換",
  "搭法甲、乙、丙的三视图完全相同（都是 2×2 的正方形），但搭法不同、方块数也可能不同。所以只凭三视图不一定能确定几何体。":
    "搭法甲、乙、丙的三視圖完全相同（都是 2×2 的正方形），但搭法不同、方塊數也可能不同。所以只憑三視圖不一定能確定幾何體。",
  "点击网格或方块的面放上一个方块（落在该列顶部）；右键、Shift + 点击或切换到“移除”可以拿走一个。":
    "點擊網格或方塊的面放上一個方塊（落在該列頂部）；右鍵、Shift + 點擊或切換到“移除”可以拿走一個。",
  "{0} 个小正方体": "{0} 個小正方體",
  "在原图中取互相垂直的 x 轴、y 轴": "在原圖中取互相垂直的 x 軸、y 軸",
  "画对应的 x′ 轴、y′ 轴，使 ∠x′O′y′ = 45°":
    "畫對應的 x′ 軸、y′ 軸，使 ∠x′O′y′ = 45°",
  "平行于 x 轴的线段长度不变，平行于 y 轴的线段长度变为原来的一半":
    "平行於 x 軸的線段長度不變，平行於 y 軸的線段長度變為原來的一半",
  "连接各点，擦去辅助线，得到直观图": "連接各點，擦去輔助線，得到直觀圖",
  原图面积: "原圖面積",
  直观图面积: "直觀圖面積",
  面积之比: "面積之比",
  演示: "演示",
  几何体认识: "幾何體認識",
  "<p>由若干个平面多边形围成的几何体叫<b>多面体</b>；由平面图形绕一条直线旋转形成的几何体叫<b>旋转体</b>。</p><p>拖动舞台旋转几何体：看不见的棱画成<b>虚线</b>，这是立体图形的画法约定。</p><p>数一数多面体的顶点数 V、棱数 E、面数 F，它们总满足<b>欧拉公式</b> V − E + F = 2。</p>":
    "<p>由若干個平面多邊形圍成的幾何體叫<b>多面體</b>；由平面圖形繞一條直線旋轉形成的幾何體叫<b>旋轉體</b>。</p><p>拖動舞臺旋轉幾何體：看不見的稜畫成<b>虛線</b>，這是立體圖形的畫法約定。</p><p>數一數多面體的頂點數 V、稜數 E、面數 F，它們總滿足<b>歐拉公式</b> V − E + F = 2。</p>",
  展开与折叠: "展開與摺疊",
  "<p>把几何体的表面沿某些棱剪开、摊平，得到它的<b>展开图</b>。表面积就是展开图的面积。</p><p>圆柱的侧面展开是矩形，圆锥的侧面展开是扇形。正方体共有 <b>11 种</b>不同的展开图。</p><p>求表面上两点间的最短路径，先把路径经过的面展开到同一平面，再连直线。</p>":
    "<p>把幾何體的表面沿某些稜剪開、攤平，得到它的<b>展開圖</b>。表面積就是展開圖的面積。</p><p>圓柱的側面展開是矩形，圓錐的側面展開是扇形。正方體共有 <b>11 種</b>不同的展開圖。</p><p>求表面上兩點間的最短路徑，先把路徑經過的面展開到同一平面，再連直線。</p>",
  三视图与直观图: "三視圖與直觀圖",
  "<p>从正前方、正左方、正上方观察几何体，分别得到<b>主视图、左视图、俯视图</b>。三者满足“长对正、高平齐、宽相等”。</p><p>在网格上点击即可叠放小方块，右键（或切换到“移除”）拿走方块，三视图同步更新。三视图相同的几何体，搭法不一定唯一。</p><p><b>斜二测画法</b>用来画水平放置的平面图形的直观图。</p>":
    "<p>從正前方、正左方、正上方觀察幾何體，分別得到<b>主視圖、左視圖、俯視圖</b>。三者滿足“長對正、高平齊、寬相等”。</p><p>在網格上點擊即可疊放小方塊，右鍵（或切換到“移除”）拿走方塊，三視圖同步更新。三視圖相同的幾何體，搭法不一定唯一。</p><p><b>斜二測畫法</b>用來畫水平放置的平面圖形的直觀圖。</p>",
  "<p>用一个平面去截几何体，得到的平面图形叫<b>截面</b>。截面的每条边都是截平面与几何体某个面的交线。</p><p>拖动棱上的三个点 P、Q、R 确定截平面，或者切换到“自由”模式调整平面的方向和位置。</p><p>正方体的截面可以是三角形、四边形、五边形、六边形，但截面三角形一定是锐角三角形，也截不出正五边形。</p>":
    "<p>用一個平面去截幾何體，得到的平面圖形叫<b>截面</b>。截面的每條邊都是截平面與幾何體某個面的交線。</p><p>拖動稜上的三個點 P、Q、R 確定截平面，或者切換到“自由”模式調整平面的方向和位置。</p><p>正方體的截面可以是三角形、四邊形、五邊形、六邊形，但截面三角形一定是銳角三角形，也截不出正五邊形。</p>",
  空间角: "空間角",
  "<p>空间角都要转化为<b>平面角</b>来求：</p><p><b>异面直线所成角</b>：平移其中一条直线，使两条直线相交，所成锐角或直角，范围 (0°, 90°]。</p><p><b>直线与平面所成角</b>：斜线与它在平面内的射影所成的角，范围 [0°, 90°]。</p><p><b>二面角</b>：在棱上取一点，在两个面内分别作垂直于棱的射线，两射线所成的角，范围 [0°, 180°]。</p><p>点击棱或对角线、面来选择对象，也可以直接选一道例题。</p>":
    "<p>空間角都要轉化為<b>平面角</b>來求：</p><p><b>異面直線所成角</b>：平移其中一條直線，使兩條直線相交，所成銳角或直角，範圍 (0°, 90°]。</p><p><b>直線與平面所成角</b>：斜線與它在平面內的射影所成的角，範圍 [0°, 90°]。</p><p><b>二面角</b>：在稜上取一點，在兩個面內分別作垂直於稜的射線，兩射線所成的角，範圍 [0°, 180°]。</p><p>點擊稜或對角線、面來選擇對象，也可以直接選一道例題。</p>",
  空间向量与坐标: "空間向量與座標",
  "<p>建立空间直角坐标系后，点有坐标，直线有<b>方向向量</b>，平面有<b>法向量</b>，空间角和距离都可以用向量运算求出，不必作辅助线。</p><p>异面直线：cos θ = |a·b| / (|a||b|)；线面角：sin θ = |a·n| / (|a||n|)；二面角：由法向量夹角得到，锐角还是钝角要看图形；点到平面的距离：d = |AP·n| / |n|。</p><p>右侧把向量法的结果与第 5 章的几何法放在一起对照。</p>":
    "<p>建立空間直角座標系後，點有座標，直線有<b>方向向量</b>，平面有<b>法向量</b>，空間角和距離都可以用向量運算求出，不必作輔助線。</p><p>異面直線：cos θ = |a·b| / (|a||b|)；線面角：sin θ = |a·n| / (|a||n|)；二面角：由法向量夾角得到，銳角還是鈍角要看圖形；點到平面的距離：d = |AP·n| / |n|。</p><p>右側把向量法的結果與第 5 章的幾何法放在一起對照。</p>",
  外接球与内切球: "外接球與內切球",
  "<p>截面、展开图、三视图三类题目，每组随机 5 题。作答后舞台会演示答案。</p>":
    "<p>截面、展開圖、三視圖三類題目，每組隨機 5 題。作答後舞臺會演示答案。</p>",
  "异面直线 A₁B 与 B₁C 所成角": "異面直線 A₁B 與 B₁C 所成角",
