  "二面角 A₁-BD-C₁": "二面角 A₁-BD-C₁",
  "侧棱 PA 与底面 ABCD 所成角": "側稜 PA 與底面 ABCD 所成角",
  "侧面 PAB 与底面所成二面角": "側面 PAB 與底面所成二面角",
