  双曲线: "雙曲線",
  "P 在截线上运动时，Q₁Q₂ 始终是两个切圆之间的一段母线，长度不变，所以 PF₁ + PF₂ 是定值。":
    "P 在截線上運動時，Q₁Q₂ 始終是兩個切圓之間的一段母線，長度不變，所以 PF₁ + PF₂ 是定值。",
  "双曲线的两个球分别在上下两个圆锥里。P 在一支上运动时，Q₁Q₂ 同样是两个切圆之间的母线长，所以 |PF₁ − PF₂| 是定值。":
    "雙曲線的兩個球分別在上下兩個圓錐裡。P 在一支上運動時，Q₁Q₂ 同樣是兩個切圓之間的母線長，所以 |PF₁ − PF₂| 是定值。",
