  "焦点到曲线上任一点的距离 |PF|，与该点到准线的距离 d 之比恒为 e。e 越小，准线越远、曲线越圆。":
    "焦點到曲線上任一點的距離 |PF|，與該點到準線的距離 d 之比恆為 e。e 越小，準線越遠、曲線越圓。",
