    "直線與漸近線平行，二次項係數為 0，方程退化為一次方程：只有一個交點，但不是相切。",
  "二次项系数为 0（直线与对称轴平行），方程退化为一次方程：只有一个交点，但不是相切。":
    "二次項係數為 0（直線與對稱軸平行），方程退化為一次方程：只有一個交點，但不是相切。",
