  焦点发光: "焦點發光",
  平行光射入: "平行光射入",
  "光线从 F₁ 出发，经椭圆反射后都经过 F₂。原因：椭圆在 P 点的法线平分 ∠F₁PF₂。":
    "光線從 F₁ 出發，經橢圓反射後都經過 F₂。原因：橢圓在 P 點的法線平分 ∠F₁PF₂。",
  "平行于轴射入的光线，反射后都汇聚到焦点：太阳灶、卫星天线就是这样聚光的。":
    "平行於軸射入的光線，反射後都匯聚到焦點：太陽灶、衛星天線就是這樣聚光的。",
  "从焦点发出的光线，反射后都平行于对称轴射出：手电筒、探照灯就是这样发出平行光的。":
    "從焦點發出的光線，反射後都平行於對稱軸射出：手電筒、探照燈就是這樣發出平行光的。",
  "光线从 F₂ 射向右支，反射光线的反向延长线（虚线）都经过另一个焦点 F₁，好像光是从 F₁ 发出的。":
    "光線從 F₂ 射向右支，反射光線的反向延長線（虛線）都經過另一個焦點 F₁，好像光是從 F₁ 發出的。",
  光源在焦点上: "光源在焦點上",
  "光源不在焦点上：反射光不再汇聚": "光源不在焦點上：反射光不再匯聚",
  反射: "反射",
  "拖动光源，靠近焦点时会自动吸附": "拖動光源，靠近焦點時會自動吸附",
  光源回到焦点: "光源回到焦點",
