  半顶角: "半頂角",
  "截面经过圆锥的顶点，截线退化为点或直线。":
    "截面經過圓錐的頂點，截線退化為點或直線。",
  "比较 β 与 α：β > α 为椭圆（β = 90° 时为圆），β = α 为抛物线，β < α 为双曲线。":
    "比較 β 與 α：β > α 為橢圓（β = 90° 時為圓），β = α 為拋物線，β < α 為雙曲線。",
  圆锥的截线: "圓錐的截線",
  "Dandelin 双球": "Dandelin 雙球",
  "<p>在圆锥里放两个球，都与圆锥相切、也与截平面相切。两个球与截平面的切点 F₁、F₂ 正是截线的<b>焦点</b>。</p><p>从球外一点引球的切线，切线长相等。截线上的点 P 到 F₁ 的距离，等于 P 沿母线到上方切圆的距离 PQ₁；同理 PF₂ = PQ₂。</p><p>所以 PF₁ + PF₂ = Q₁Q₂，是两个切圆之间的母线长，与 P 的位置无关：这就是椭圆的定义。</p>":
    "<p>在圓錐裡放兩個球，都與圓錐相切、也與截平面相切。兩個球與截平面的切點 F₁、F₂ 正是截線的<b>焦點</b>。</p><p>從球外一點引球的切線，切線長相等。截線上的點 P 到 F₁ 的距離，等於 P 沿母線到上方切圓的距離 PQ₁；同理 PF₂ = PQ₂。</p><p>所以 PF₁ + PF₂ = Q₁Q₂，是兩個切圓之間的母線長，與 P 的位置無關：這就是橢圓的定義。</p>",
  "<p>平面内到两个定点 F₁、F₂ 的距离之和等于常数 2a（2a > |F₁F₂|）的点的轨迹叫<b>椭圆</b>。</p><p>把细绳两端钉在焦点上，用笔拉紧绳子转一圈，就画出一个椭圆。</p><p>标准方程 x²/a² + y²/b² = 1（a > b > 0），其中 <b>a² = b² + c²</b>，离心率 e = c/a 越接近 1，椭圆越扁。</p>":
    "<p>平面內到兩個定點 F₁、F₂ 的距離之和等於常數 2a（2a > |F₁F₂|）的點的軌跡叫<b>橢圓</b>。</p><p>把細繩兩端釘在焦點上，用筆拉緊繩子轉一圈，就畫出一個橢圓。</p><p>標準方程 x²/a² + y²/b² = 1（a > b > 0），其中 <b>a² = b² + c²</b>，離心率 e = c/a 越接近 1，橢圓越扁。</p>",
  "<p>平面内到一个定点 F 和一条定直线 l（F 不在 l 上）的距离相等的点的轨迹叫<b>抛物线</b>。F 是焦点，l 是准线。</p><p>标准方程 y² = 2px（p > 0），焦点 (p/2, 0)，准线 x = −p/2。p 是焦点到准线的距离。</p><p>过焦点且垂直于对称轴的弦叫<b>通径</b>，长为 2p。</p>":
    "<p>平面內到一個定點 F 和一條定直線 l（F 不在 l 上）的距離相等的點的軌跡叫<b>拋物線</b>。F 是焦點，l 是準線。</p><p>標準方程 y² = 2px（p > 0），焦點 (p/2, 0)，準線 x = −p/2。p 是焦點到準線的距離。</p><p>過焦點且垂直於對稱軸的弦叫<b>通徑</b>，長為 2p。</p>",
  光学性质: "光學性質",
  "<p>从椭圆一个焦点发出的光，经椭圆反射后汇聚到<b>另一个焦点</b>。</p><p>从抛物线焦点发出的光，反射后<b>平行于对称轴</b>射出，探照灯、卫星天线都用这个原理。</p><p>从双曲线一个焦点发出的光，反射后的反向延长线经过<b>另一个焦点</b>。</p><p>拖动光源离开焦点，反射光就不再汇聚。</p>":
    "<p>從橢圓一個焦點發出的光，經橢圓反射後匯聚到<b>另一個焦點</b>。</p><p>從拋物線焦點發出的光，反射後<b>平行於對稱軸</b>射出，探照燈、衛星天線都用這個原理。</p><p>從雙曲線一個焦點發出的光，反射後的反向延長線經過<b>另一個焦點</b>。</p><p>拖動光源離開焦點，反射光就不再匯聚。</p>",
  直线与圆锥曲线: "直線與圓錐曲線",
  被遮挡的线: "被遮擋的線",
  辅助线: "輔助線",
