  "海里格·冯·科赫，1904": "海里格·馮·科赫，1904",
  边数: "邊數",
  "每一级周长变为原来的 4/3 倍，无限增大；面积只增加越来越小的一点，最终是原三角形的 8/5 倍。一条无限长的曲线围出了有限的面积。用滚轮放大，细节永远看不完。":
    "每一級周長變為原來的 4/3 倍，無限增大；面積只增加越來越小的一點，最終是原三角形的 8/5 倍。一條無限長的曲線圍出了有限的面積。用滾輪放大，細節永遠看不完。",
  长一级: "長一級",
  自动生长: "自動生長",
  "圆环（0 个半扭）": "圓環（0 個半扭）",
  "莫比乌斯带（1 个）": "莫比烏斯帶（1 個）",
