  "点击偏振片可让它转过 15°。液晶屏的每个像素就是一个可以通断电的液晶盒，夹在两块正交偏振片之间。":
    "點擊偏振片可讓它轉過 15°。液晶螢幕的每個像素就是一個可以通斷電的液晶盒，夾在兩塊正交偏振片之間。",
  棱镜顶角: "稜鏡頂角",
