  "测量头：6 条亮纹求平均": "測量頭：6 條亮紋求平均",
  中央亮纹宽度: "中央亮紋寬度",
  "双缝干涉条纹等间距、亮度几乎相同；外侧略暗是因为每条缝本身的衍射。":
    "雙縫干涉條紋等間距、亮度幾乎相同；外側略暗是因為每條縫本身的繞射。",
  "单缝衍射的中央亮纹最宽最亮，宽度是两侧亮纹的两倍；缝越窄，条纹越宽。":
    "單縫繞射的中央亮紋最寬最亮，寬度是兩側亮紋的兩倍；縫越窄，條紋越寬。",
  "光栅缝多，主极大又细又亮；刻线越密，光谱展得越开。":
    "光柵縫多，主極大又細又亮；刻線越密，光譜展得越開。",
