  当前没有可导出的数据: "目前沒有可匯出的資料",
  光纤: "光纖",
  光屏到透镜的距离: "光屏到透鏡的距離",
  显示光路: "顯示光路",
  棱镜转角: "稜鏡轉角",
  第二块倒置棱镜: "第二塊倒置稜鏡",
