  "靠近：f′ = f·v/(v − vₛ)": "靠近：f′ = f·v/(v − vₛ)",
  "远离：f′ = f·v/(v + vₛ)": "遠離：f′ = f·v/(v + vₛ)",
  "马赫角 sinμ = v/vₛ": "馬赫角 sinμ = v/vₛ",
  "台面上的波面按缩小的声速绘制（示意）；频率按真实声速 340 m/s 计算。救护车驶近时音调变高、驶离时变低，测速雷达、彩超也利用了多普勒效应。":
    "檯面上的波面按縮小的聲速繪製（示意）；頻率按真實聲速 340 m/s 計算。救護車駛近時音調變高、駛離時變低，測速雷達、彩色超音波也利用了都卜勒效應。",
