  加强线: "加強線",
  "两波源连线上的加强线条数由 d/λ 决定：频率越高（波长越短）或两波源越远，加强线越密。黄色实线为加强线，蓝色虚线为减弱线。":
    "兩波源連線上的加強線條數由 d/λ 決定：頻率越高（波長越短）或兩波源越遠，加強線越密。黃色實線為加強線，藍色虛線為減弱線。",
