  "推片留下的血膜呈舌形：起始端厚，红细胞重叠、成缗钱状；中段细胞单层分布、刚好相接，是观察和计数的理想区域；末端呈羽毛状，细胞稀少、常变形。":
    "推片留下的血膜呈舌形：起始端厚，紅血球重疊、成錢串狀；中段細胞單層分布、剛好相接，是觀察和計數的理想區域；末端呈羽毛狀，細胞稀少、常變形。",
  "蛙的红细胞呈椭圆形、有细胞核，比人的红细胞大得多。":
    "蛙的紅血球呈橢圓形、有細胞核，比人的紅血球大得多。",
