  壳缝: "殼縫",
  "<p>硅藻的细胞壁由<b>二氧化硅</b>构成，像带盖的盒子，壳面上有排列整齐的<b>线纹和孔纹</b>。清洗后的壳几乎无色透明，是检验物镜<b>分辨率</b>的经典标本。</p><p>布纹藻的线纹间距约 0.55 µm：40× 物镜下看不清，100× 油镜（缩小视场、开大孔径光阑）才能分辨。比较明场、暗场和相差下的效果。</p>":
    "<p>矽藻的細胞壁由<b>二氧化矽</b>構成，像有蓋的盒子，殼面上有排列整齊的<b>線紋和孔紋</b>。清洗後的殼幾乎無色透明，是檢驗物鏡<b>解析度</b>的經典標本。</p><p>布紋藻的線紋間距約 0.55 µm：40× 物鏡下看不清，100× 油鏡（縮小視野、開大孔徑光圈）才能分辨。比較明視野、暗視野和相位差下的效果。</p>",
  黑藻叶片: "黑藻葉片",
  黑藻叶: "黑藻葉",
  临时装片: "臨時玻片",
