  "叶绿体（随细胞质流动）": "葉綠體（隨細胞質流動）",
  "换 40× 观察胞质环流": "換 40× 觀察胞質環流",
  视野中央: "視野中央",
  没有叶片细胞: "沒有葉片細胞",
  中央细胞环流方向: "中央細胞環流方向",
  顺时针: "順時針",
