  该细胞叶绿体数: "該細胞葉綠體數",
  "胞质环流：活细胞的细胞质沿着中央大液泡的周围循环流动，叶绿体随之移动，可作为流动的标志。显微镜成倒像（旋转 180°），不改变环流方向——视野中看到顺时针，实际也是顺时针。相邻细胞的流向常常相反；温度适当升高、光照增强时流动加快。":
    "胞質環流：活細胞的細胞質沿著中央大液泡的周圍循環流動，葉綠體隨之移動，可作為流動的標誌。顯微鏡成倒像（旋轉 180°），不改變環流方向——視野中看到順時針，實際也是順時針。相鄰細胞的流向常常相反；溫度適當升高、光照增強時流動加快。",
