  "25 × 16 型": "25 × 16 型",
  "中央 1 mm × 1 mm 的大方格分为 25 个中方格（三线分隔），每个中方格又分为 16 个小方格。计数室深 0.1 mm，所以一个小方格上方的体积是 2.5 × 10⁻⁷ mL。":
    "中央 1 mm × 1 mm 的大方格分為 25 個中方格（三線分隔），每個中方格又分為 16 個小方格。計數室深 0.1 mm，所以一個小方格上方的體積是 2.5 × 10⁻⁷ mL。",
  "数四角和中央共 5 个中方格（80 个小方格），压线的细胞计上不计下、计左不计右；出芽的酵母菌按一个计。":
    "數四角和中央共 5 個中方格（80 個小方格），壓線的細胞計上不計下、計左不計右；出芽的酵母菌按一個計。",
