  "叶片横切：表皮（保护组织）、叶肉（营养组织：栅栏组织含叶绿体多，海绵组织排列疏松）、叶脉（输导组织：导管运输水和无机盐，筛管运输有机物）。番红把木质化的导管壁染成红色，固绿把纤维素壁和细胞质染成绿色。":
    "葉片橫切：表皮（保護組織）、葉肉（營養組織：柵狀組織含葉綠體多，海綿組織排列疏鬆）、葉脈（輸導組織：導管運輸水和無機鹽，篩管運輸有機物）。番紅把木質化的導管壁染成紅色，固綠把纖維素壁和細胞質染成綠色。",
  字母装片: "字母玻片",
