  "刻度格（10 µm）": "刻度格（10 µm）",
  "刻度说明：1 mm 分为 100 格": "刻度說明：1 mm 分為 100 格",
  "台微尺全长 1 mm，分为 100 格，每格 10 µm。把目镜测微尺与台微尺的 0 刻度对齐，找出两尺刻线再次重合的位置，即可算出目镜测微尺每格代表的长度。":
    "台微尺全長 1 mm，分為 100 格，每格 10 µm。把目鏡測微尺與台微尺的 0 刻度對齊，找出兩尺刻線再次重合的位置，即可算出目鏡測微尺每格代表的長度。",
