  "碎屑（细菌团）": "碎屑（細菌團）",
  "<p>草履虫靠纤毛摆动前进，同时绕身体长轴旋转，所以走的是螺旋形路线。碰到障碍时纤毛反向摆动：先后退，再转一个角度前进（避让反应）。</p><p>伸缩泡周围的收集管先把水收集起来，注入伸缩泡；伸缩泡胀大后突然收缩，把多余的水排出体外，两个伸缩泡交替进行。</p>":
    "<p>草履蟲靠纖毛擺動前進，同時繞身體長軸旋轉，所以走的是螺旋形路線。碰到障礙時纖毛反向擺動：先後退，再轉一個角度前進（避讓反應）。</p><p>伸縮泡周圍的收集管先把水收集起來，注入伸縮泡；伸縮泡脹大後突然收縮，把多餘的水排出體外，兩個伸縮泡交替進行。</p>",
  松花粉: "松花粉",
  向日葵花粉: "向日葵花粉",
  百合花粉: "百合花粉",
  木槿花粉: "木槿花粉",
  玉米花粉: "玉米花粉",
  南瓜花粉: "南瓜花粉",
  花粉粒装片: "花粉粒玻片",
  花粉粒: "花粉粒",
  混合: "混合",
  "松花粉（本体）": "松花粉（本體）",
  松花粉的气囊: "松花粉的氣囊",
  外壁上的刺: "外壁上的刺",
  萌发沟: "萌發溝",
  "<p>花粉粒的<b>外壁</b>有各种纹饰（刺、网纹）和<b>萌发孔 / 萌发沟</b>，形态是鉴定植物的依据。松花粉有两个<b>气囊</b>，适于风媒传粉；向日葵、木槿花粉具刺，为虫媒花粉。</p><p>花粉粒较厚：<b>调节细准焦螺旋</b>，可依次看到表面纹饰、光学切面的轮廓和另一面的纹饰。</p>":
    "<p>花粉粒的<b>外壁</b>有各種紋飾（刺、網紋）和<b>萌發孔 / 萌發溝</b>，形態是鑑定植物的依據。松花粉有兩個<b>氣囊</b>，適於風媒傳粉；向日葵、木槿花粉具刺，為蟲媒花粉。</p><p>花粉粒較厚：<b>調節細調節輪</b>，可依次看到表面紋飾、光學切面的輪廓和另一面的紋飾。</p>",
  洋葱根尖有丝分裂装片: "洋蔥根尖有絲分裂玻片",
  洋葱根尖: "洋蔥根尖",
  "染色质丝（前期）": "染色質絲（前期）",
  细胞板: "細胞板",
  子细胞核: "子細胞核",
  染色体: "染色體",
  "赤道板位置（并无实际结构）": "赤道板位置（並無實際結構）",
  纺锤体: "紡錘體",
  导管: "導管",
  根冠细胞: "根冠細胞",
  分生区细胞: "分生區細胞",
  伸长区细胞: "伸長區細胞",
  成熟区细胞: "成熟區細胞",
  "<p><b>洋葱根尖</b>（2n = 16）压片，甲紫染色。分生区细胞呈正方形、排列紧密，细胞核大；伸长区细胞变长，不再分裂。</p><p>视野中大多数细胞处于<b>间期</b>——间期在细胞周期中占的时间最长。</p>":
    "<p><b>洋蔥根尖</b>（2n = 16）壓片，龍膽紫染色。分生區細胞呈正方形、排列緊密，細胞核大；伸長區細胞變長，不再分裂。</p><p>視野中大多數細胞處於<b>間期</b>——間期在細胞週期中占的時間最長。</p>",
  水绵: "水綿",
  胶质鞘: "膠質鞘",
  "横壁（细胞壁）": "橫壁（細胞壁）",
  接合孢子: "接合孢子",
  接合管: "接合管",
  "空的细胞（原生质体已移出）": "空的細胞（原生質體已移出）",
  蛋白核: "蛋白核",
  带状叶绿体: "帶狀葉綠體",
  "<p>水绵的叶绿体呈带状、螺旋排列。上下调节细准焦螺旋：靠近你的一半螺旋带与远离的一半斜向相反，交替变清楚。带上的小圆点是蛋白核，滴加碘液后变蓝黑色（含淀粉）。</p>":
    "<p>水綿的葉綠體呈帶狀、螺旋排列。上下調節細調節輪：靠近你的一半螺旋帶與遠離的一半斜向相反，交替變清楚。帶上的小圓點是蛋白核，滴加碘液後變藍黑色（含澱粉）。</p>",
  蚕豆叶下表皮: "蠶豆葉下表皮",
  蚕豆叶: "蠶豆葉",
  撕破的细胞: "撕破的細胞",
  "气孔（张开）": "氣孔（張開）",
  "气孔（关闭）": "氣孔（關閉）",
  保卫细胞加厚的内壁: "保衛細胞加厚的內壁",
  "叶肉细胞（撕取时带下）": "葉肉細胞（撕取時帶下）",
  "细胞壁（波状）": "細胞壁（波狀）",
  表皮细胞: "表皮細胞",
  "蚕豆叶下表皮：表皮细胞无色透明、彼此嵌合；成对的保卫细胞围成气孔，保卫细胞含叶绿体。下表皮的气孔比上表皮多。":
    "蠶豆葉下表皮：表皮細胞無色透明、彼此嵌合；成對的保衛細胞圍成氣孔，保衛細胞含葉綠體。下表皮的氣孔比上表皮多。",
  "可以亲手操作的写实光学显微镜：转动粗细准焦螺旋、转换器、遮光器与反光镜，目镜视野按真实光学成像——倒像、景深、分辨率、离焦光晕、明场 / 暗场 / 相差；26 种玻片，覆盖规范操作、观察动植物细胞、质壁分离、有丝分裂、油镜、测微尺与血球计数板。":
    "可以親手操作的寫實光學顯微鏡：轉動粗細調節輪、旋轉盤、光圈盤與反光鏡，目鏡視野按真實光學成像——倒像、景深、解析度、離焦光暈、明視野 / 暗視野 / 相位差；26 種玻片，涵蓋規範操作、觀察動植物細胞、質壁分離、有絲分裂、油鏡、測微尺與血球計數板。",
