  涂膜: "塗膜",
  "<b>细菌</b>很小，要用<b>油镜</b>（100×）观察：先在低倍镜下找到涂膜较薄、颜色较淡的地方，滴加香柏油后换油镜。革兰染色后，<b>革兰阳性菌</b>呈紫色，<b>革兰阴性菌</b>呈红色。":
    "<b>細菌</b>很小，要用<b>油鏡</b>（100×）觀察：先在低倍鏡下找到塗膜較薄、顏色較淡的地方，滴加香柏油後換油鏡。革蘭染色後，<b>革蘭陽性菌</b>呈紫色，<b>革蘭陰性菌</b>呈紅色。",
  骨骼肌纵切: "骨骼肌縱切",
  骨骼肌: "骨骼肌",
  "纵切 HE": "縱切 HE",
  "细胞核（位于肌纤维周边）": "細胞核（位於肌纖維周邊）",
  "肌纤维（横纹：暗带、明带）": "肌纖維（橫紋：暗帶、明帶）",
  "结缔组织（肌束膜）": "結締組織（肌束膜）",
  "<b>骨骼肌</b>：肌纤维呈长圆柱形，有许多细胞核，位于细胞周边；有明显的<b>横纹</b>。换 40× 物镜并缩小光圈，横纹开始显现；用油镜可以看清暗带（A 带）、明带（I 带）和 Z 线。":
    "<b>骨骼肌</b>：肌纖維呈長圓柱形，有許多細胞核，位於細胞周邊；有明顯的<b>橫紋</b>。換 40× 物鏡並縮小光圈，橫紋開始顯現；用油鏡可以看清暗帶（A 帶）、明帶（I 帶）和 Z 線。",
  "脊髓涂片（运动神经元）": "脊髓塗片（運動神經元）",
  脊髓涂片: "脊髓塗片",
  运动神经元: "運動神經元",
  "细胞体（含尼氏体）": "細胞體（含尼氏體）",
  轴突: "軸突",
  树突: "樹突",
  神经纤维网与神经胶质细胞: "神經纖維網與神經膠質細胞",
  "<b>神经元</b>由细胞体和突起组成。突起分为<b>树突</b>（多而短、反复分支）和<b>轴突</b>（一条，细而长，粗细均匀）。细胞体中被碱性染料染成蓝紫色的颗粒叫尼氏体。":
    "<b>神經元</b>由細胞體和突起組成。突起分為<b>樹突</b>（多而短、反覆分支）和<b>軸突</b>（一條，細而長，粗細均勻）。細胞體中被鹼性染料染成藍紫色的顆粒叫尼氏體。",
  "花生子叶切片（苏丹Ⅲ染色）": "花生子葉切片（蘇丹Ⅲ染色）",
  花生子叶: "花生子葉",
  苏丹Ⅲ染色: "蘇丹Ⅲ染色",
  "细胞外的脂肪滴（切破的细胞放出）": "細胞外的脂肪滴（切破的細胞放出）",
  "脂肪滴（被苏丹Ⅲ染成橘黄色）": "脂肪滴（被蘇丹Ⅲ染成橘黃色）",
  "<b>检测脂肪</b>：苏丹Ⅲ染液把脂肪染成<b>橘黄色</b>（苏丹Ⅳ染成红色）。染色后用 50% 酒精洗去浮色，先在低倍镜下找到最薄的部位，再换高倍镜观察细胞中的脂肪颗粒。":
    "<b>檢測脂肪</b>：蘇丹Ⅲ染液把脂肪染成<b>橘黃色</b>（蘇丹Ⅳ染成紅色）。染色後用 50% 酒精洗去浮色，先在低倍鏡下找到最薄的部位，再換高倍鏡觀察細胞中的脂肪顆粒。",
  "青霉（棉蓝染色）": "青黴（棉藍染色）",
  青霉: "青黴",
  乳酸酚棉蓝: "乳酸酚棉藍",
  分生孢子: "分生孢子",
  小梗: "小梗",
  "梗基（帚状枝）": "梗基（帚狀枝）",
  分生孢子梗: "分生孢子梗",
  "菌丝（有横隔）": "菌絲（有橫隔）",
  "<b>青霉</b>是多细胞真菌，菌丝有横隔。直立菌丝（分生孢子梗）顶端分枝成<b>扫帚状</b>，生出成串的<b>分生孢子</b>，孢子落到适宜的环境中就会萌发成新个体。曲霉的孢子梗顶端则膨大成球状。":
    "<b>青黴</b>是多細胞真菌，菌絲有橫隔。直立菌絲（分生孢子梗）頂端分枝成<b>掃帚狀</b>，生出成串的<b>分生孢子</b>，孢子落到適宜的環境中就會萌發成新個體。麴黴的孢子梗頂端則膨大成球狀。",
  马铃薯淀粉粒: "馬鈴薯澱粉粒",
  马铃薯: "馬鈴薯",
  脐点: "臍點",
  复粒淀粉粒: "複粒澱粉粒",
  "淀粉粒（层纹）": "澱粉粒（層紋）",
  向日葵茎横切: "向日葵莖橫切",
  向日葵幼茎: "向日葵幼莖",
  "横切 番红固绿": "橫切 番紅固綠",
  "导管（木质部）": "導管（木質部）",
  表皮: "表皮",
  "厚角组织（皮层）": "厚角組織（皮層）",
  皮层薄壁细胞: "皮層薄壁細胞",
  髓射线: "髓射線",
  髓: "髓",
  木质部: "木質部",
  韧皮部: "韌皮部",
  "韧皮纤维（纤维帽）": "韌皮纖維（纖維帽）",
  "<b>双子叶植物茎</b>的维管束排成一圈，束中有<b>形成层</b>，能使茎逐年加粗。番红把木质化的细胞壁（导管、纤维）染成红色，固绿把纤维素细胞壁染成绿色。先用 4× 物镜看清整体结构，再换高倍镜观察一个维管束。":
    "<b>雙子葉植物莖</b>的維管束排成一圈，束中有<b>形成層</b>，能使莖逐年加粗。番紅把木質化的細胞壁（導管、纖維）染成紅色，固綠把纖維素細胞壁染成綠色。先用 4× 物鏡看清整體結構，再換高倍鏡觀察一個維管束。",
  数据坞: "數據塢",
  "视野是模糊的：先转粗准焦螺旋（Shift+滚轮）找到物像，再用细准焦螺旋（滚轮）调清晰":
    "視野是模糊的：先轉粗調節輪（Shift+滾輪）找到物像，再用細調節輪（滾輪）調清晰",
  自动演示研究级显微镜的操作: "自動演示研究級顯微鏡的操作",
  停止演示: "停止演示",
  "研究级显微镜由光源、聚光器、载物台、物镜转换器、目镜和调焦机构组成。下面按规范步骤演示一遍。":
    "研究級顯微鏡由光源、聚光器、載物台、物鏡轉換器、目鏡和調焦機構組成。下面按規範步驟演示一遍。",
  "打开电源，转动亮度调节旋钮，把光源调到适中的亮度。":
    "打開電源，轉動亮度調節旋鈕，把光源調到適中的亮度。",
  "转动物镜转换器，使 4× 低倍物镜对准光路，听到“咔”的一声即转到位。":
    "轉動物鏡轉換器，使 4× 低倍物鏡對準光路，聽到「咔」的一聲即轉到位。",
  "把玻片放到载物台上，盖玻片朝上，用玻片夹夹好。":
    "把玻片放到載物台上，蓋玻片朝上，用玻片夾夾好。",
  "转动载物台移动旋钮，把标本移到通光孔的正中央。":
    "轉動載物台移動旋鈕，把標本移到通光孔的正中央。",
  "眼睛从侧面看着物镜，转动粗准焦螺旋，使载物台上升到接近物镜（不要碰到玻片）。":
    "眼睛從側面看著物鏡，轉動粗準焦螺旋，使載物台上升到接近物鏡（不要碰到玻片）。",
  "眼睛看着目镜，反向慢慢转动粗准焦螺旋使载物台下降，直到视野中出现物像。":
    "眼睛看著目鏡，反向慢慢轉動粗準焦螺旋使載物台下降，直到視野中出現物像。",
  "再转动细准焦螺旋，使物像最清晰。": "再轉動細準焦螺旋，使物像最清晰。",
  "调节聚光器下的孔径光阑：缩小时对比度增强、景深变大，开大时分辨率更高。一般开到物镜孔径的 2/3 左右。":
    "調節聚光器下的孔徑光闌：縮小時對比度增強、景深變大，開大時解析度更高。一般開到物鏡孔徑的 2/3 左右。",
  "换高倍镜：先把要观察的细胞移到视野中央，再转动转换器换上 40× 物镜。物镜是齐焦的，换镜后物像仍基本清楚。":
    "換高倍鏡：先把要觀察的細胞移到視野中央，再轉動轉換器換上 40× 物鏡。物鏡是齊焦的，換鏡後物像仍基本清楚。",
  "高倍镜下只能用细准焦螺旋微调；视野变暗了，就把光源调亮一些。":
    "高倍鏡下只能用細準焦螺旋微調；視野變暗了，就把光源調亮一些。",
  "转动聚光器转盘，还可以切换暗场和相差照明，观察透明的结构。":
    "轉動聚光器轉盤，還可以切換暗場和相差照明，觀察透明的結構。",
  "演示结束。显微镜已经调好，现在轮到你亲手操作了！":
    "演示結束。顯微鏡已經調好，現在輪到你親手操作了！",
