  自由探索: "自由探索",
  "<p>所有参数都已开放。试着组合不同的条件，观察水循环各环节怎样变化：</p><p>· 强向陆风 + 夏季：迎风坡暴雨，河流水量大<br>· 冬季：山地积雪，河流靠地下水补给<br>· 毁林 + 高硬化率 + 暴雨：洪峰陡涨<br>· 全球变暖：雪线上升，冰川退缩</p>":
    "<p>所有參數都已開放。試著組合不同的條件，觀察水循環各環節怎樣變化：</p><p>· 強向陸風 + 夏季：迎風坡暴雨，河流水量大<br>· 冬季：山地積雪，河流靠地下水補給<br>· 毀林 + 高硬化率 + 暴雨：洪峰陡漲<br>· 全球變暖：雪線上升，冰川退縮</p>",
  基础: "基礎",
  水循环过程: "水循環過程",
  影响与意义: "影響與意義",
  综合: "綜合",
  人类活动对水循环影响最大的环节是: "人類活動對水循環影響最大的環節是",
  "修建水库、跨流域调水、城市硬化等，主要改变的都是地表径流。水汽输送、降水等发生在大气中，人类难以直接干预（人工增雨只是局部）。":
    "修建水庫、跨流域調水、城市硬化等，主要改變的都是地表徑流。水汽輸送、降水等發生在大氣中，人類難以直接干預（人工增雨只是局部）。",
  "使陆地水资源不断得到补充、更新的水循环类型是":
    "使陸地水資源不斷得到補充、更新的水循環類型是",
  三者作用相同: "三者作用相同",
  "海陆间循环把海洋蒸发的水汽输送到陆地上空形成降水，使陆地水不断得到补充。":
    "海陸間循環把海洋蒸發的水汽輸送到陸地上空形成降水，使陸地水不斷得到補充。",
  "城市路面大面积硬化后，城市河流的变化是":
    "城市路面大面積硬化後，城市河流的變化是",
  "洪峰流量增大，峰现时间提前": "洪峰流量增大，峰現時間提前",
  "洪峰流量减小，峰现时间推迟": "洪峰流量減小，峰現時間推遲",
  "地下径流增加，枯水期流量增大": "地下徑流增加，枯水期流量增大",
  "下渗增加，地表径流减少": "下滲增加，地表徑流減少",
  "硬化地面不透水，下渗减少、地表径流增加，雨水经排水管网迅速汇入河道，所以洪峰更高、来得更早；地下水补给减少，枯水期流量反而变小。":
    "硬化地面不透水，下滲減少、地表徑流增加，雨水經排水管網迅速匯入河道，所以洪峰更高、來得更早；地下水補給減少，枯水期流量反而變小。",
  我国西北内陆盆地的水循环主要属于: "我國西北內陸盆地的水循環主要屬於",
  不参与水循环: "不參與水循環",
  "内陆盆地深居内陆，河流注入内陆湖或消失在沙漠中，不流入海洋，是陆地内循环。":
    "內陸盆地深居內陸，河流注入內陸湖或消失在沙漠中，不流入海洋，是陸地內循環。",
  南水北调工程主要影响水循环的: "南水北調工程主要影響水循環的",
