    "跨流域調水把一個流域的地表水引到另一個流域，改變了地表徑流的空間分佈。",
  植树造林对水循环的影响是: "植樹造林對水循環的影響是",
  "下渗增加，地表径流减少，蒸腾增加": "下滲增加，地表徑流減少，蒸騰增加",
  "下渗减少，地表径流增加": "下滲減少，地表徑流增加",
  "降水减少，蒸发减少": "降水減少，蒸發減少",
  对水循环没有影响: "對水循環沒有影響",
  "林冠截留和疏松的枯枝落叶层使雨水更多地下渗，地表径流减少；植物蒸腾增加了大气中的水汽。":
    "林冠截留和疏鬆的枯枝落葉層使雨水更多地下滲，地表徑流減少；植物蒸騰增加了大氣中的水汽。",
  参与水量最大的水循环类型是: "參與水量最大的水循環類型是",
  三者相同: "三者相同",
  "海洋面积广、蒸发量大，大部分水汽在海洋上空就凝结降回海洋。":
    "海洋面積廣、蒸發量大，大部分水汽在海洋上空就凝結降回海洋。",
  下列不属于水循环地理意义的是: "下列不屬於水循環地理意義的是",
