  使淡水资源不断更新: "使淡水資源不斷更新",
  "水循环不会让各地降水趋于相同，降水的地区差异依然很大。其余三项都是水循环的意义。":
    "水循環不會讓各地降水趨於相同，降水的地區差異依然很大。其餘三項都是水循環的意義。",
